// Author: MiYu. Source persistent passives use real nearby units, damage, cyclone carriers and command-driven Tornado wandering.
#include "session.h"
#include <algorithm>
#include <bit>
#include <cmath>
namespace war3 {
namespace {
float number(jass::Real value){return std::bit_cast<float>(value.bits());}
jass::Real real(float value){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(value));}
int cell(float value){return int(std::clamp(std::floor(double(value)/512),double(INT_MIN),double(INT_MAX)));}
std::uint64_t key(int x,int y){return (std::uint64_t(std::uint32_t(x))<<32)|std::uint32_t(y);}
bool ambient(PassiveKind kind){return kind==PassiveKind::PermanentImmolation || kind==PassiveKind::TornadoDamage || kind==PassiveKind::TornadoSpin || kind==PassiveKind::TornadoWander || kind==PassiveKind::Barrage || kind==PassiveKind::PlagueAura;}
}
void ScriptSession::refreshAmbientPassives(UnitState& u,const std::map<std::uint32_t,unsigned>& abilities){
    std::set<std::uint32_t> desired;if(!u.removing && !u.illusion)for(auto [ability,level]:abilities){auto& p=passiveInfo(ability,level);if(!ambient(p.kind))continue;desired.insert(ability);auto [found,created]=ambientClocks_.try_emplace({u.handle,ability});auto& clock=found->second;if(created || clock.level!=level){for(auto effect:clock.visuals)destroyEffect(effect);if(!created){auto oldBuff=passiveInfo(ability,clock.level).buff;if(auto mark=u.buffs.find(oldBuff);mark!=u.buffs.end() && mark->second.kind==BuffKind::Mark && mark->second.originAbility==ability){releaseBuff(mark->second);u.buffs.erase(mark);}}clock={};clock.level=level;clock.deathRevision=u.deathRevision;clock.ownerRevision=u.ownerRevision;clock.home={u.x,u.y};clock.remaining=p.period;}}
    for(auto it=ambientClocks_.lower_bound({u.handle,0});it!=ambientClocks_.end() && it->first.first==u.handle;)if(!desired.contains(it->first.second)){for(auto effect:it->second.visuals)destroyEffect(effect);auto buff=passiveInfo(it->first.second,it->second.level).buff;if(auto mark=u.buffs.find(buff);mark!=u.buffs.end() && mark->second.kind==BuffKind::Mark && mark->second.originAbility==it->first.second){releaseBuff(mark->second);u.buffs.erase(mark);}it=ambientClocks_.erase(it);}else ++it;if(desired.empty())ambientActors_.erase(u.handle);else ambientActors_.insert(u.handle);
}
void ScriptSession::removeAmbientPassives(std::uint32_t unit){
    ambientActors_.erase(unit);for(auto it=ambientClocks_.lower_bound({unit,0});it!=ambientClocks_.end() && it->first.first==unit;){for(auto effect:it->second.visuals)destroyEffect(effect);it=ambientClocks_.erase(it);}
}
std::vector<std::uint32_t> ScriptSession::ambientNearby(WorldPoint point,float radius){
    float x=number(point.x),y=number(point.y);int left=cell(x-radius-512),right=cell(x+radius+512),bottom=cell(y-radius-512),top=cell(y+radius+512);std::vector<std::uint32_t> result;double buckets=(double(right)-left+1)*(double(top)-bottom+1);if(buckets>double(units_.size())*2){for(auto& [id,u]:units_)result.push_back(id);}else for(std::int64_t row=bottom;row<=top;++row)for(std::int64_t column=left;column<=right;++column)if(auto found=ambientGrid_.find(key(int(column),int(row)));found!=ambientGrid_.end())result.insert(result.end(),found->second.begin(),found->second.end());std::sort(result.begin(),result.end());return result;
}
void ScriptSession::ambientPassivesTick(double delta){
    if(ambientActors_.empty()){ambientGrid_.clear();return;}std::vector<std::pair<std::uint32_t,std::uint32_t>> due;std::vector<std::uint32_t> actors(ambientActors_.begin(),ambientActors_.end());for(auto id:actors){if(!alive(id,NativeKind::Unit)){removeAmbientPassives(id);continue;}auto u=units_.at(id);for(auto it=ambientClocks_.lower_bound({id,0});it!=ambientClocks_.end() && it->first.first==id;++it){auto& clock=it->second;auto& p=passiveInfo(it->first.second,clock.level);auto available=config_.players[u->owner].abilityAvailable.find(p.ability);bool enabled=available==config_.players[u->owner].abilityAvailable.end() || available->second;if(u->removing || u->hidden() || u->morphed() || u->construction || number(u->life)<=0 || !enabled){for(auto effect:clock.visuals)destroyEffect(effect);clock.visuals.clear();if(p.kind==PassiveKind::PermanentImmolation){auto mark=u->buffs.find(p.buff);if(mark!=u->buffs.end() && mark->second.kind==BuffKind::Mark && mark->second.originAbility==p.ability){releaseBuff(mark->second);u->buffs.erase(mark);}}clock.remaining=p.period;continue;}if(u->paused)continue;if(clock.deathRevision!=u->deathRevision || clock.ownerRevision!=u->ownerRevision){for(auto effect:clock.visuals)destroyEffect(effect);clock.visuals.clear();clock.deathRevision=u->deathRevision;clock.ownerRevision=u->ownerRevision;clock.home={u->x,u->y};clock.remaining=p.period;}if(p.kind==PassiveKind::PermanentImmolation && p.buff && !u->buffs.contains(p.buff)){UnitBuff mark;mark.id=p.buff;mark.source=mark.target=id;mark.kind=BuffKind::Mark;mark.remaining=p.period;mark.positive=mark.persistent=true;mark.dispellable=false;mark.originAbility=p.ability;mark.sourceLevel=p.level;mark.sourceOwner=u->owner;u->buffs[p.buff]=std::move(mark);}if(p.kind==PassiveKind::PlagueAura && clock.visuals.empty()){SpellInfo art;art.ability=p.ability;clock.visuals=spellVisual(art,"TargetArt",id,{u->x,u->y},false);}if(p.kind==PassiveKind::PermanentImmolation && clock.visuals.empty() && p.buff){SpellInfo art;art.ability=p.buff;clock.visuals=spellVisual(art,"TargetArt",id,{u->x,u->y},false);}clock.remaining-=delta;if(clock.remaining<=0){clock.remaining+=p.period;due.push_back(it->first);}}}
    if(due.empty())return;ambientGrid_.clear();for(auto& [id,u]:units_)if(!u->removing && !u->hidden() && number(u->life)>0)ambientGrid_[key(cell(number(u->x)),cell(number(u->y)))].push_back(id);for(auto source:due){auto found=ambientClocks_.find(source);if(found==ambientClocks_.end() || !alive(source.first,NativeKind::Unit))continue;auto u=units_.at(source.first);if(u->removing || u->paused || u->hidden() || u->morphed() || number(u->life)<=0)continue;auto& p=passiveInfo(source.second,found->second.level);auto available=config_.players[u->owner].abilityAvailable.find(p.ability);if(available!=config_.players[u->owner].abilityAvailable.end() && !available->second)continue;ambientPulse(source.first,p,found->second);}
}
void ScriptSession::ambientPulse(std::uint32_t id,const PassiveInfo& p,AmbientClock& clock){
    auto u=units_.at(id);auto owner=u->owner;auto death=u->deathRevision,ownership=u->ownerRevision;auto active=[&]{return alive(id,NativeKind::Unit) && !u->removing && !u->paused && !u->hidden() && !u->morphed() && number(u->life)>0 && u->owner==owner && u->deathRevision==death && u->ownerRevision==ownership;};
    if(p.kind==PassiveKind::PlagueAura){plaguePulse(id,p);return;}
    if(p.kind==PassiveKind::Barrage){barragePulse(id,p,clock);return;}
    if(p.kind==PassiveKind::TornadoWander){if(u->holding || !u->route.empty() || u->cast || u->combat.target || u->currentOrder)return;auto home=clock.home;for(unsigned attempt=0;attempt<16;++attempt){float angle=float(double(random())/4294967296.*6.28318530718),radius=std::sqrt(float(double(random())/4294967296.))*p.nearArea;auto point=requireWorld().clamp({real(number(u->x)+std::cos(angle)*radius),real(number(u->y)+std::sin(angle)*radius)});if(std::hypot(number(point.x)-number(home.x),number(point.y)-number(home.y))>p.area)continue;if(moveUnit(id,point,851986))return;}return;}
    auto candidates=ambientNearby({u->x,u->y},p.area);if(p.kind==PassiveKind::TornadoSpin){std::vector<std::uint32_t> targets;for(auto target:candidates){if(target==id || !alive(target,NativeKind::Unit))continue;auto victim=units_.at(target);if(victim->cycloned() || victim->airborne() || victim->building || capability(*victim,"Amim") || !passiveTarget(*u,*victim,p) || std::hypot(number(victim->x)-number(u->x),number(victim->y)-number(u->y))>p.area+victim->collision)continue;targets.push_back(target);}if(targets.empty())return;auto target=targets[random()%targets.size()];SpellInfo spin;spin.kind=SpellKind::Cyclone;spin.ability=p.ability;spin.level=p.level;spin.buff=p.buff;spin.guardBuff=p.buff;spin.duration=p.amount;spin.heroDuration=p.heroDuration;spin.allowed=p.allowed;spin.dispellable=true;cycloneEffect(id,target,spin);return;}
    for(auto target:candidates){if(!active())return;if(target==id || !alive(target,NativeKind::Unit))continue;auto victim=units_.at(target);float distance=std::hypot(number(victim->x)-number(u->x),number(victim->y)-number(u->y));if(distance>p.area+victim->collision || !passiveTarget(*u,*victim,p))continue;float damage=p.amount;if(p.kind==PassiveKind::TornadoDamage){if(p.innerArea>0 && distance<=p.innerArea+victim->collision)damage=p.innerDamage;else if(p.nearArea>0 && distance<=p.nearArea+victim->collision)damage=p.nearDamage;}if(damage<=0)continue;auto revision=victim->deathRevision;damageUnit(id,target,damage,0,p.kind==PassiveKind::PermanentImmolation?8:26);if(active() && alive(target,NativeKind::Unit) && !victim->removing && number(victim->life)>0 && victim->deathRevision==revision && p.buff){SpellInfo art;art.ability=p.buff;spellVisual(art,"SpecialArt",target,{victim->x,victim->y});if(p.kind==PassiveKind::TornadoDamage){SpellInfo mark;mark.ability=p.ability;mark.buff=p.buff;mark.duration=mark.heroDuration=p.period+1.f/32;applyBuff(target,id,mark,BuffKind::Mark);}}}
}
void ScriptSession::pulverizeDamage(const CombatProjectile& projectile,const PassiveInfo& p){
    if(!alive(projectile.source,NativeKind::Unit) || !alive(projectile.target,NativeKind::Unit))return;auto source=units_.at(projectile.source),target=units_.at(projectile.target);if(source->removing || source->illusion || number(source->life)<=0)return;auto death=source->deathRevision,ownership=source->ownerRevision;WorldPoint point{target->x,target->y};std::vector<std::uint32_t> victims;for(auto& [id,u]:units_)if(id!=projectile.source && passiveTarget(*source,*u,p) && std::hypot(number(u->x)-number(point.x),number(u->y)-number(point.y))<=p.innerArea+u->collision)victims.push_back(id);SpellInfo art;art.ability=p.ability;spellVisual(art,"Casterart",projectile.source,{source->x,source->y});for(auto id:victims){if(!alive(projectile.source,NativeKind::Unit) || source->removing || number(source->life)<=0 || source->deathRevision!=death || source->ownerRevision!=ownership)return;if(!alive(id,NativeKind::Unit) || !passiveTarget(*source,*units_.at(id),p))continue;auto u=units_.at(id);float distance=std::hypot(number(u->x)-number(point.x),number(u->y)-number(point.y));if(distance>p.innerArea+u->collision)continue;damageUnit(projectile.source,id,p.secondary*(distance<=p.nearArea+u->collision?1.f:.5f),1,4);if(alive(id,NativeKind::Unit))spellVisual(art,"Specialart",id,{units_.at(id)->x,units_.at(id)->y});}
}
}
